# Generated by build.py from recipe.yml for recipe smtp-send-and-read-it-over-imap. Do not edit.
Set-Location $PSScriptRoot
[IO.File]::WriteAllText((Join-Path $PWD 'lunch.txt'), "From: ann@example.com`nTo: bob@example.com`nSubject: Lunch`n`nNoon at the usual place.`n")
$server0 = Start-Process surl -ArgumentList '--allow-anonymous', 'smtp://127.0.0.1:8080/', 'imap://127.0.0.1:8081/', 'pop3://127.0.0.1:8082/' -PassThru -NoNewWindow
Start-Sleep 1
try { curl.exe --crlf --mail-from ann@example.com --mail-rcpt bob@example.com -T lunch.txt smtp://127.0.0.1:8080/example.com --next "imap://127.0.0.1:8081/INBOX;UID=1;SECTION=TEXT" } finally { Stop-Process $server0 }
